pchy <- function(x) {
    if(!is.ts(x)) stop("x is not a timeseries")

    x.freq <- tsp(x)[3]
    if(!(x.freq %in% c(1,2,4,12))) stop("Invalid frequency of timeseries x (must be 1, 2, 4, 12)")

    y <- diff(x,lag=x.freq)/lag(x,-x.freq)
    return(y)
}

